const express = require('express');
const { DynamicTool } = require('@langchain/core/tools');
const { verifyRecruiterToken } = require('../auth');
const { CandidateEvaluation, JobOpening } = require('../models/candidate');

const app = express();
app.use(express.json());

app.post('/api/recruitment/agent/tools/evaluation', verifyRecruiterToken, async (req, res) => {
  const { candidateId } = req.body;
  if (!candidateId) return res.status(400).json({ error: 'Candidate ID required' });

  const evalData = await CandidateEvaluation.findOne({
    where: { candidateId },
    include: [{ model: JobOpening, as: 'job' }]
  });

  if (!evalData) return res.status(404).json({ error: 'Evaluation not found' });

  // Ensure recruiter belongs to the department managing this candidate requisition
  if (evalData.job.departmentId !== req.user.departmentId && req.user.role !== 'TALENT_HEAD') {
    return res.status(403).json({ error: 'Access denied to candidate outside your department' });
  }

  const candidateReviewTool = new DynamicTool({
    name: 'fetch_candidate_evaluation',
    description: 'Fetches interview scores and compensation requirements',
    func: async () => JSON.stringify(evalData)
  });

  const result = await candidateReviewTool.call(candidateId);
  res.json({ evaluation: JSON.parse(result) });
});

app.listen(8119);
